parameters.jsCode:
const reponse = $input.first().json;
const offresOriginales = $('Construire le prompt').first().json.offres;

// Un appel en echec (quota depasse, service indisponible) ne renvoie aucun candidat. Les offres
// du lot sont alors marquees en echec technique : le noeud suivant les laisse en 'new' pour
// quelles soient reproposees au prochain lancement, au lieu de les consommer sans analyse.
const texteBrut = reponse.candidates?.[0]?.content?.parts?.[0]?.text ?? '';

let resultatsIA = null;
if (texteBrut) {
  try {
    resultatsIA = JSON.parse(texteBrut.replace(/```json/g, '').replace(/```/g, '').trim());
  } catch (erreur) {
    resultatsIA = null;
  }
}

if (!Array.isArray(resultatsIA)) {
  return offresOriginales.map(offre => ({ json: { ...offre, echecTechnique: true, score: null, analyse: null, lettre: null } }));
}

return offresOriginales.map((offre, index) => {
  const resultat = resultatsIA[index];
  if (!resultat) {
    return { json: { ...offre, echecTechnique: true, score: null, analyse: null, lettre: null } };
  }
  return {
    json: {
      id: offre.id,
      title: offre.title,
      company: offre.company,
      location: offre.location,
      link: offre.link,
      echecTechnique: false,
      score: Number(resultat.score),
      type_piste: resultat.type_piste ?? 'inconnue',
      analyse: resultat.analyse ?? '',
      lettre: resultat.lettre ?? ''
    }
  };
});

// Mots-cles technologiques ou de domaine incompatibles avec le profil (stack reelle :
// React/Node/TypeScript/MySQL, pas Java ni Angular - voir discussion du 17/08).
// Match volontairement conservateur : seuls des signaux non ambigus sont retenus.
const MOTS_CLES_ELIMINATOIRES = [
  { motif: /\bjava\b/i, raison: 'Java (hors stack : React/Node/TypeScript)' },
  { motif: /\bangular\b/i, raison: 'Angular (hors stack : React/Node/TypeScript)' },
  { motif: /\bcobol\b/i, raison: 'COBOL' },
  { motif: /\bmainframe\b/i, raison: 'Mainframe' },
  { motif: /automat(isme|icien)/i, raison: 'Automatisme industriel' }
];

return $input.all().map(item => {
  const texte = `${item.json.title || ''} ${item.json.description || ''}`;
  const correspondance = MOTS_CLES_ELIMINATOIRES.find(regle => regle.motif.test(texte));

  item.json.est_elimine = Boolean(correspondance);
  item.json.raison_elimination = correspondance ? correspondance.raison : '';
  return item;
});

const offres = $json.offres;

// Le profil candidat (competences, contraintes geographiques, pistes recherchees) est lu en base
// par le node 'Profil candidat' (table candidate_profile), afin que ce workflow exporte ne
// contienne aucune donnee personnelle.
const descriptionProfil = $('Profil candidat').first().json.profil;

const listeOffres = offres.map((offre, index) =>
  `--- OFFRE ${index} ---
Type de contrat (donnee fiable de la source) : ${offre.contract_type}
Titre : ${offre.title}
Entreprise : ${offre.company}
Lieu de travail : ${offre.location}
Description : ${offre.description}`
).join('

');

const consignes = `

Voici ${offres.length} offres a analyser, numerotees de 0 a ${offres.length - 1}.

Pour CHAQUE offre, applique ces regles dans l'ordre :

1. Note l'offre sur 20.

   REGLE GEOGRAPHIQUE, prioritaire sur toutes les autres :
   Si le lieu de travail n'est pas dans la metropole lilloise ET que l'offre ne propose pas un teletravail
   integral, la note ne depasse pas 4 sur 20, quelle que soit la qualite technique de l'offre.

   REGLES SELON LA PISTE :
   - Type de contrat ALTERNANCE : evalue l'offre pour la PISTE A.
     Plafonne a 8 sur 20 si l'offre exige un niveau bac+5 deja acquis, ou plus de deux ans d'experience.
     Plafonne a 8 sur 20 si le rythme annonce est incompatible avec 3 semaines entreprise / 1 semaine ecole.
   - Type de contrat CDI : evalue l'offre pour la PISTE B.
     Plafonne a 8 sur 20 si l'offre exige plus de trois ans d'experience, ou vise un profil senior, lead ou architecte.
     Plafonne a 6 sur 20 si le poste n'est pas un poste de developpement.
   - Tout autre type de contrat : la note ne depasse pas 4 sur 20.

   Le type de contrat fourni provient des donnees structurees de la source et fait foi. Ne le deduis pas
   du texte : une offre mentionnant « une premiere experience en alternance » designe un poste classique.

2. Renseigne "type_piste" avec "alternance" ou "cdi", selon le type de contrat fourni.

3. Dans "analyse", commence par indiquer le lieu et le type de contrat, puis donne ton avis en deux phrases maximum.

4. Redige une lettre de motivation complete et personnalisee, prete a etre envoyee. Adapte-la a la piste.

Reponds UNIQUEMENT avec un tableau JSON de ${offres.length} elements, sans bloc markdown autour, dans le MEME ORDRE que les offres ci-dessus. Chaque element a exactement ces quatre champs : score (nombre entier), type_piste (chaine), analyse (chaine), lettre (chaine).`;

return [{
  json: {
    offres: offres,
    promptText: descriptionProfil + '

' + listeOffres + consignes
  }
}];
